<template><div class="page"><div class="page-head"><div><h1 class="page-title">借阅规则</h1><div class="page-sub">按读者类型配置借阅期限、续借和逾期费用</div></div></div><el-alert title="规则修改后只影响新产生的借阅记录，历史记录不会自动变化。" type="warning" show-icon :closable="false" style="margin-bottom:18px"/><div class="rule-grid"><el-card v-for="r in rows" :key="r.id"><template #header><div class="rule-head"><div class="rule-icon"><el-icon><UserFilled/></el-icon></div><div><b>{{r.readerType==='STUDENT'?'学生读者':'教师读者'}}</b><small>{{r.readerType}}</small></div><el-button text type="primary" @click="edit(r)">编辑</el-button></div></template><div class="rule-list"><p><span>最大借阅数量</span><b>{{r.maxCount}} 本</b></p><p><span>借阅期限</span><b>{{r.borrowDays}} 天</b></p><p><span>最大续借次数</span><b>{{r.maxRenewCount}} 次</b></p><p><span>每次续借</span><b>{{r.renewDays}} 天</b></p><p><span>每日逾期费用</span><b>¥ {{r.dailyFine}}</b></p></div></el-card></div><el-dialog v-model="visible" title="编辑借阅规则" width="500"><el-form label-position="top"><div class="form-grid"><el-form-item label="最大借阅数量"><el-input-number v-model="form.maxCount"/></el-form-item><el-form-item label="借阅期限（天）"><el-input-number v-model="form.borrowDays"/></el-form-item><el-form-item label="最大续借次数"><el-input-number v-model="form.maxRenewCount"/></el-form-item><el-form-item label="续借天数"><el-input-number v-model="form.renewDays"/></el-form-item><el-form-item label="每日罚款"><el-input-number v-model="form.dailyFine" :precision="2" :step="0.1"/></el-form-item></div></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存规则</el-button></template></el-dialog></div></template><script setup lang="ts">import{ref,reactive,onMounted}from'vue';import api from'../api';import{ElMessage}from'element-plus';const rows=ref<any[]>([]),visible=ref(false),form=reactive<any>({});onMounted(load);async function load(){rows.value=await api.get('/api/system/rules')}function edit(r:any){Object.assign(form,r);visible.value=true}async function save(){await api.put(`/api/system/rules/${form.id}`,form);ElMessage.success('规则已更新');visible.value=false;load()}</script><style scoped>.rule-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:18px;max-width:900px}.rule-head{display:flex;align-items:center;gap:12px}.rule-icon{width:42px;height:42px;border-radius:12px;background:#e4f6ef;color:#23946f;display:grid;place-items:center;font-size:20px}.rule-head small{display:block;color:#9aa6b3;margin-top:4px}.rule-head .el-button{margin-left:auto}.rule-list p{display:flex;justify-content:space-between;padding:11px 0;border-bottom:1px solid #eef2f5;margin:0}.rule-list span{color:#748396}.form-grid{display:grid;grid-template-columns:1fr 1fr}</style>

